-- growth_sprint_demo.sql
-- Growth Sprint Experience v1 — demo dataset
--
-- Three real, golden-case-validated Growth Sprints (not placeholder text) —
-- captured from live Anthropic API runs after both pilot-readiness fixes
-- (Growth Moment completeness gating + corrected decision_outcome logic).
-- Safe to run any number of times (upsert on id). Requires migration
-- 0067_growth_sprint_experience.sql to already be applied.
--
-- Each demo sprint is fully published, with a share token that is ALSO
-- printed as a comment next to its insert — these are demo-only tokens,
-- not secrets, safe to use for showing the public share page in a demo.

-- PawStop (Demo) — demo share token: 6Cqh7QvdSzsY5yBbLWspkTDNmuvsjX6l
-- (visit /growth-sprint/share/6Cqh7QvdSzsY5yBbLWspkTDNmuvsjX6l once deployed)
insert into public.growth_sprints (
  id, business_name, business_location, business_context, target_customer,
  growth_question, desired_outcome, current_obstacle, constraints_notes,
  revenue_pillars, growth_moments, evidence_tags,
  diagnosis_raw, diagnosis_reviewed, recommendation_raw, recommendation_reviewed,
  decision_outcome, status, model_used, created_at, updated_at, approved_at, published_at
) values (
  'd1000000-0000-4000-8000-000000000001', 'PawStop (Demo)', 'Petaling Jaya, Malaysia', 'commerce', 'pet owners who shop for food/supplies regularly',
  'How do we grow revenue from the customers we already have, without just running more promotions?', 'Higher average revenue per existing customer', 'Grooming service exists but is barely used, and there''s no real loyalty program', 'Small team, cannot add new services this quarter — must work within existing offering',
  '["pet food & supplies retail","grooming services"]'::jsonb, '[{"id":"m1","customer":"regular food/supply buyers","situation":"comes in monthly to restock food","trigger":"asks staff a question about their pet''s skin/coat or general health at checkout","need":"reassurance the pet is okay + a convenient way to act on it","behaviour":"leaves without booking grooming or any health-related service, despite asking","commercial_response":"staff currently has no structured way to offer grooming in that moment"}]'::jsonb, '{"m1":{"confidence":"Observed","note":"staff have mentioned this happens often at checkout, no formal tracking"}}'::jsonb,
  '{"business_situation":"PawStop is a pet food and supplies retailer in Petaling Jaya with an existing grooming service that is significantly underutilised. Their existing customer base consists of regular, returning buyers who restock monthly — meaning the repeat visit behaviour is already established. The core challenge is that revenue per customer is not growing, and the business wants to change that without running more promotions or adding new services. A specific checkout behaviour has been observed by staff: customers who are already buying regularly will spontaneously raise health or coat concerns about their pets, yet leave without booking grooming — the one adjacent service that directly addresses those concerns. There is no structured mechanism to bridge that conversational moment into a commercial action, and no loyalty program to deepen ongoing engagement.","growth_constraints":["Cannot add new services this quarter — must work within pet food/supplies retail and grooming only","Small team — any solution must be low-operational-overhead and executable by existing staff","No formal tracking system currently in place for checkout interactions or grooming conversion","Growth must come from existing customers, not new customer acquisition","Cannot rely on promotions as the primary lever"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"This is the only Growth Moment identified, and it is a high-quality one: the customer has already self-disclosed a need (skin/coat or health concern), is physically present, is mid-transaction, and has an emotional openness to help. The gap is entirely on the supply side — staff have no structured response to bridge the expressed need to the grooming service.","supporting_evidence":["Staff have observed this checkout behaviour happening often","Customers leave without booking grooming despite the conversational opening","Staff currently have no structured way to respond to or convert that moment","Grooming service already exists but is barely used","Customers are regular monthly restockers"],"missing_evidence":["Frequency data: how often per week or month does this checkout interaction actually occur","Conversion baseline: what percentage of customers who ask health questions have ever booked grooming","Grooming capacity: how many grooming slots are available and unfilled each week","Customer-to-grooming service awareness: do regular buyers even know PawStop offers grooming","Staff confidence level using a script/prompt tool"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"business_situation":"PawStop is a pet food and supplies retailer in Petaling Jaya with an existing grooming service that is significantly underutilised. Their existing customer base consists of regular, returning buyers who restock monthly — meaning the repeat visit behaviour is already established. The core challenge is that revenue per customer is not growing, and the business wants to change that without running more promotions or adding new services. A specific checkout behaviour has been observed by staff: customers who are already buying regularly will spontaneously raise health or coat concerns about their pets, yet leave without booking grooming — the one adjacent service that directly addresses those concerns. There is no structured mechanism to bridge that conversational moment into a commercial action, and no loyalty program to deepen ongoing engagement.","growth_constraints":["Cannot add new services this quarter — must work within pet food/supplies retail and grooming only","Small team — any solution must be low-operational-overhead and executable by existing staff","No formal tracking system currently in place for checkout interactions or grooming conversion","Growth must come from existing customers, not new customer acquisition","Cannot rely on promotions as the primary lever"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"This is the only Growth Moment identified, and it is a high-quality one: the customer has already self-disclosed a need (skin/coat or health concern), is physically present, is mid-transaction, and has an emotional openness to help. The gap is entirely on the supply side — staff have no structured response to bridge the expressed need to the grooming service.","supporting_evidence":["Staff have observed this checkout behaviour happening often","Customers leave without booking grooming despite the conversational opening","Staff currently have no structured way to respond to or convert that moment","Grooming service already exists but is barely used","Customers are regular monthly restockers"],"missing_evidence":["Frequency data: how often per week or month does this checkout interaction actually occur","Conversion baseline: what percentage of customers who ask health questions have ever booked grooming","Grooming capacity: how many grooming slots are available and unfilled each week","Customer-to-grooming service awareness: do regular buyers even know PawStop offers grooming","Staff confidence level using a script/prompt tool"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"growth_hypothesis":"We believe that regular monthly food/supply buyers who verbally raise a skin, coat, or health concern at checkout will convert to a booked grooming appointment at a meaningful rate if staff follow a simple scripted prompt and offer an on-the-spot booking in that same interaction — because the customer has already self-disclosed a need, is physically present, and the only current barrier is the absence of a structured staff response.","thirty_day_test":"Over 30 days, equip all checkout staff with a one-page laminated prompt card that (a) lists two to three short verbal responses to common skin/coat/health questions and (b) includes a QR code or direct link to the grooming booking calendar. Staff log each instance on a simple tally sheet, recording: date, question type, whether the grooming offer was made, and whether the customer booked, asked for more info, or declined. No discount or promotion is offered.","target_audience":"Regular monthly food and supply buyers who verbally raise a question about their pet''s skin, coat, or general health during the checkout interaction","offer_intervention":"A scripted verbal prompt from staff bridging the expressed health concern to the existing grooming service, paired with an immediate on-the-spot booking opportunity via a visible booking link or QR code — no price change, no promotion, structural response only","conversion_path":"Customer raises skin/coat/health question at checkout → staff delivers scripted acknowledgement and names grooming as a relevant next step → staff offers to check availability immediately or hands customer QR code to book → customer books in-store or books within 48 hours via the link","evidence_signals":["Total number of qualifying checkout interactions logged","Number of times staff successfully delivered the grooming offer when the trigger occurred","Number of grooming bookings made in-store at the moment of offer","Number of grooming bookings made within 48 hours via the QR/link","Conversion rate: bookings divided by qualifying interactions where the offer was made","Staff-reported friction or hesitation using the script"],"decision_rule":"After the 30-day test has run: if the offer was made in at least 20 qualifying interactions and conversion to booked grooming appointment is 15% or higher, move to Scale. If conversion is between 5% and 14%, move to Retest with a specific named adjustment. If fewer than 20 qualifying interactions were logged, move to Retest with a focus on staff logging compliance or extending the window. If conversion is below 5% despite consistent offer delivery, move to Shift and evaluate a different intervention. If staff adoption was below 50% of logged interactions, the test is not yet valid — Retest with a training/accountability adjustment.","decision_rationale":"No prior test of this specific intervention has been run at PawStop. The evidence confirms the problem exists but confirms nothing about whether a structured prompt will change customer behaviour. Hold is the only honest current state: the test has not run, the conversion rate is unknown, and staff adoption is unproven.","decision_outcome":"Hold"}'::jsonb, '{"growth_hypothesis":"We believe that regular monthly food/supply buyers who verbally raise a skin, coat, or health concern at checkout will convert to a booked grooming appointment at a meaningful rate if staff follow a simple scripted prompt and offer an on-the-spot booking in that same interaction — because the customer has already self-disclosed a need, is physically present, and the only current barrier is the absence of a structured staff response.","thirty_day_test":"Over 30 days, equip all checkout staff with a one-page laminated prompt card that (a) lists two to three short verbal responses to common skin/coat/health questions and (b) includes a QR code or direct link to the grooming booking calendar. Staff log each instance on a simple tally sheet, recording: date, question type, whether the grooming offer was made, and whether the customer booked, asked for more info, or declined. No discount or promotion is offered.","target_audience":"Regular monthly food and supply buyers who verbally raise a question about their pet''s skin, coat, or general health during the checkout interaction","offer_intervention":"A scripted verbal prompt from staff bridging the expressed health concern to the existing grooming service, paired with an immediate on-the-spot booking opportunity via a visible booking link or QR code — no price change, no promotion, structural response only","conversion_path":"Customer raises skin/coat/health question at checkout → staff delivers scripted acknowledgement and names grooming as a relevant next step → staff offers to check availability immediately or hands customer QR code to book → customer books in-store or books within 48 hours via the link","evidence_signals":["Total number of qualifying checkout interactions logged","Number of times staff successfully delivered the grooming offer when the trigger occurred","Number of grooming bookings made in-store at the moment of offer","Number of grooming bookings made within 48 hours via the QR/link","Conversion rate: bookings divided by qualifying interactions where the offer was made","Staff-reported friction or hesitation using the script"],"decision_rule":"After the 30-day test has run: if the offer was made in at least 20 qualifying interactions and conversion to booked grooming appointment is 15% or higher, move to Scale. If conversion is between 5% and 14%, move to Retest with a specific named adjustment. If fewer than 20 qualifying interactions were logged, move to Retest with a focus on staff logging compliance or extending the window. If conversion is below 5% despite consistent offer delivery, move to Shift and evaluate a different intervention. If staff adoption was below 50% of logged interactions, the test is not yet valid — Retest with a training/accountability adjustment.","decision_rationale":"No prior test of this specific intervention has been run at PawStop. The evidence confirms the problem exists but confirms nothing about whether a structured prompt will change customer behaviour. Hold is the only honest current state: the test has not run, the conversion rate is unknown, and staff adoption is unproven.","decision_outcome":"Hold"}'::jsonb,
  'Hold', 'published', 'claude-sonnet-4-6', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z'
)
on conflict (id) do update set
  diagnosis_raw = excluded.diagnosis_raw, diagnosis_reviewed = excluded.diagnosis_reviewed,
  recommendation_raw = excluded.recommendation_raw, recommendation_reviewed = excluded.recommendation_reviewed,
  status = excluded.status, updated_at = excluded.updated_at;

