-- Recover Physio (Demo) — demo share token: W1pmW_XORhgEqnnh40LeZ1_9iF0bUQaE
-- (visit /growth-sprint/share/W1pmW_XORhgEqnnh40LeZ1_9iF0bUQaE once deployed)
insert into public.growth_sprints (
  id, business_name, business_location, business_context, target_customer,
  growth_question, desired_outcome, current_obstacle, constraints_notes,
  revenue_pillars, growth_moments, evidence_tags,
  diagnosis_raw, diagnosis_reviewed, recommendation_raw, recommendation_reviewed,
  decision_outcome, status, model_used, created_at, updated_at, approved_at, published_at
) values (
  'd1000000-0000-4000-8000-000000000002', 'Recover Physio (Demo)', 'Kuala Lumpur', 'service', 'people with new or recurring pain considering physio for the first time',
  'How do we convert more first-time inquiries into booked initial consultations?', 'Higher inquiry-to-booking conversion rate', 'Many people message to ask about pricing or whether physio is ''worth it'', then go quiet', 'Cannot discount the first session — clinic has a strict no-discounting policy for credibility reasons',
  '["initial consultations","ongoing treatment packages"]'::jsonb, '[{"id":"m1","customer":"first-time inquirers","situation":"messages the clinic on Instagram/WhatsApp asking about a specific pain or injury","trigger":"pain has become bad enough to consider professional help, but they''ve never done physio before","need":"reassurance that this is the right kind of help, and clarity on cost/expectations before committing","behaviour":"asks 1-2 questions then stops replying, never books","commercial_response":"currently just replies with price and a generic booking link"}]'::jsonb, '{"m1":{"confidence":"Confirmed","note":"front desk has logged this drop-off pattern for the last 2 months"}}'::jsonb,
  '{"business_situation":"Recover Physio is a physiotherapy clinic in Kuala Lumpur targeting first-time physio seekers who are experiencing new or recurring pain. The clinic''s confirmed drop-off problem occurs specifically at the inquiry stage: prospective patients message asking about their pain or pricing, receive a price and a generic booking link in response, then go silent. This pattern has been logged by front desk staff over the past two months. The clinic cannot use discounting as a conversion lever due to a firm no-discounting policy maintained for credibility purposes.","growth_constraints":["No discounting of the first session — clinic policy, non-negotiable","Drop-off happens asynchronously over WhatsApp/Instagram DM, limiting real-time intervention","First-time physio seekers have low category knowledge, meaning generic responses do not address their actual hesitation","Front desk is currently the only touchpoint handling inquiries"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"The drop-off is not caused by price alone — it is caused by the clinic''s response failing to address the two needs the inquirer actually has: reassurance and clarity on what to expect. Sending a price and a booking link answers neither.","supporting_evidence":["Front desk has logged the ask-then-go-quiet drop-off pattern for the last 2 months","Inquirers explicitly ask about a specific pain or injury","Inquirers ask whether physio is ''worth it'', signalling reassurance is the missing element","Current commercial response is price + generic booking link","No-discounting constraint rules out price reduction as a lever"],"missing_evidence":["What specific pain types or injuries are most commonly mentioned","How quickly front desk is responding to inquiries","Whether inquirers who do book had a different conversation","Volume of inquiries per week","Whether inquirers are comparing multiple clinics simultaneously"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"business_situation":"Recover Physio is a physiotherapy clinic in Kuala Lumpur targeting first-time physio seekers who are experiencing new or recurring pain. The clinic''s confirmed drop-off problem occurs specifically at the inquiry stage: prospective patients message asking about their pain or pricing, receive a price and a generic booking link in response, then go silent. This pattern has been logged by front desk staff over the past two months. The clinic cannot use discounting as a conversion lever due to a firm no-discounting policy maintained for credibility purposes.","growth_constraints":["No discounting of the first session — clinic policy, non-negotiable","Drop-off happens asynchronously over WhatsApp/Instagram DM, limiting real-time intervention","First-time physio seekers have low category knowledge, meaning generic responses do not address their actual hesitation","Front desk is currently the only touchpoint handling inquiries"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"The drop-off is not caused by price alone — it is caused by the clinic''s response failing to address the two needs the inquirer actually has: reassurance and clarity on what to expect. Sending a price and a booking link answers neither.","supporting_evidence":["Front desk has logged the ask-then-go-quiet drop-off pattern for the last 2 months","Inquirers explicitly ask about a specific pain or injury","Inquirers ask whether physio is ''worth it'', signalling reassurance is the missing element","Current commercial response is price + generic booking link","No-discounting constraint rules out price reduction as a lever"],"missing_evidence":["What specific pain types or injuries are most commonly mentioned","How quickly front desk is responding to inquiries","Whether inquirers who do book had a different conversation","Volume of inquiries per week","Whether inquirers are comparing multiple clinics simultaneously"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"growth_hypothesis":"We believe that replacing the current price-and-link reply with a two-part response — one sentence validating that the described pain or injury is something physio can address, plus a brief description of what the first appointment involves — will materially increase the share of first-time Instagram/WhatsApp inquirers who book an appointment, because the current drop-off is driven by unmet reassurance and expectation needs, not by price objection alone.","thirty_day_test":"For every first-time Instagram or WhatsApp inquiry that describes a specific pain or injury, front desk replaces the current reply with a structured three-part message: (1) a condition-specific acknowledgement, (2) a concrete description of the first appointment, and (3) a direct, low-friction prompt to book. Front desk logs every inquiry received and whether it converted. No price change, no discount.","target_audience":"First-time inquirers who contact Recover Physio via Instagram DM or WhatsApp, describe a specific pain or injury, and have no prior booking history","offer_intervention":"A structured, condition-specific reassurance-and-expectation reply that replaces the generic price-plus-booking-link response","conversion_path":"Inquirer describes pain → front desk sends structured three-part reply within the same business day → inquirer receives acknowledgement plus clear appointment expectation → front desk asks a direct booking question → inquirer replies and books, or front desk follows up once within 24 hours","evidence_signals":["Inquiry-to-booking conversion rate across the 30-day test window compared to the 2-month baseline","Number of inquiries that received the new structured reply versus the old reply","Rate of inquirers who reply to the structured message versus who go quiet","Average time between inquiry and front desk reply","Which pain types or injury descriptions appear most frequently"],"decision_rule":"After the 30-day test: Scale if conversion rate increases by 20 percentage points or more relative to baseline and the structured reply was used for at least 15 inquiries. Shift if conversion does not improve but a pattern emerges suggesting a different intervention is better supported. Retest if fewer than 15 inquiries were received, the script was not used consistently, or response lag varied significantly. Stop if conversion is flat or declines across a clean sample of 15+ inquiries where the script was used as written.","decision_rationale":"Hold is the correct current state because no prior test of this specific intervention has been run. The evidence confirms the drop-off pattern is real and systemic, and the diagnosis identifies response quality as the primary available lever, but confirming a problem exists is not the same as confirming a fix works. Hold is not a hedge; it is the honest description of an untested hypothesis.","decision_outcome":"Hold"}'::jsonb, '{"growth_hypothesis":"We believe that replacing the current price-and-link reply with a two-part response — one sentence validating that the described pain or injury is something physio can address, plus a brief description of what the first appointment involves — will materially increase the share of first-time Instagram/WhatsApp inquirers who book an appointment, because the current drop-off is driven by unmet reassurance and expectation needs, not by price objection alone.","thirty_day_test":"For every first-time Instagram or WhatsApp inquiry that describes a specific pain or injury, front desk replaces the current reply with a structured three-part message: (1) a condition-specific acknowledgement, (2) a concrete description of the first appointment, and (3) a direct, low-friction prompt to book. Front desk logs every inquiry received and whether it converted. No price change, no discount.","target_audience":"First-time inquirers who contact Recover Physio via Instagram DM or WhatsApp, describe a specific pain or injury, and have no prior booking history","offer_intervention":"A structured, condition-specific reassurance-and-expectation reply that replaces the generic price-plus-booking-link response","conversion_path":"Inquirer describes pain → front desk sends structured three-part reply within the same business day → inquirer receives acknowledgement plus clear appointment expectation → front desk asks a direct booking question → inquirer replies and books, or front desk follows up once within 24 hours","evidence_signals":["Inquiry-to-booking conversion rate across the 30-day test window compared to the 2-month baseline","Number of inquiries that received the new structured reply versus the old reply","Rate of inquirers who reply to the structured message versus who go quiet","Average time between inquiry and front desk reply","Which pain types or injury descriptions appear most frequently"],"decision_rule":"After the 30-day test: Scale if conversion rate increases by 20 percentage points or more relative to baseline and the structured reply was used for at least 15 inquiries. Shift if conversion does not improve but a pattern emerges suggesting a different intervention is better supported. Retest if fewer than 15 inquiries were received, the script was not used consistently, or response lag varied significantly. Stop if conversion is flat or declines across a clean sample of 15+ inquiries where the script was used as written.","decision_rationale":"Hold is the correct current state because no prior test of this specific intervention has been run. The evidence confirms the drop-off pattern is real and systemic, and the diagnosis identifies response quality as the primary available lever, but confirming a problem exists is not the same as confirming a fix works. Hold is not a hedge; it is the honest description of an untested hypothesis.","decision_outcome":"Hold"}'::jsonb,
  'Hold', 'published', 'claude-sonnet-4-6', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z', '2026-08-19T06:57:14.057Z'
)
on conflict (id) do update set
  diagnosis_raw = excluded.diagnosis_raw, diagnosis_reviewed = excluded.diagnosis_reviewed,
  recommendation_raw = excluded.recommendation_raw, recommendation_reviewed = excluded.recommendation_reviewed,
  status = excluded.status, updated_at = excluded.updated_at;

insert into public.growth_sprint_shares (growth_sprint_id, token_hash)
values ('d1000000-0000-4000-8000-000000000002', 'f057677fed42b5b59825af36308100306401a0f76b5e21433a0c0027a85be8c2')
