-- Claymind Studio (Demo) — demo share token: FKJ1zEqX51b3msNoE2Z3ZNwipoyJm56j
-- (visit /growth-sprint/share/FKJ1zEqX51b3msNoE2Z3ZNwipoyJm56j once deployed)
insert into public.growth_sprints (
  id, business_name, business_location, business_context, target_customer,
  growth_question, desired_outcome, current_obstacle, constraints_notes,
  revenue_pillars, growth_moments, evidence_tags,
  diagnosis_raw, diagnosis_reviewed, recommendation_raw, recommendation_reviewed,
  decision_outcome, status, model_used, created_at, updated_at, approved_at, published_at
) values (
  'd1000000-0000-4000-8000-000000000003', 'Claymind Studio (Demo)', 'Penang', NULL, 'adults looking for a creative outlet / stress relief',
  'How do we grow bookings without just discounting our workshops?', 'More repeat bookings, not just one-off attendees', 'Most people attend one workshop and never come back, even when they say they loved it', 'Cannot add more workshop slots — studio space is the bottleneck',
  '["in-person pottery/craft workshops","take-home starter kits sold at the end of class"]'::jsonb, '[{"id":"m1","customer":"first-time workshop attendees","situation":"finishes a 2-hour workshop and is visibly proud of what they made","trigger":"staff mention it takes weeks to fire/glaze the piece, so there''s a gap before they get their finished item","need":"something to keep the momentum/excitement going during that gap, and a clear next step","behaviour":"leaves, picks up the piece weeks later, and doesn''t book again","commercial_response":"no follow-up currently happens between the workshop and the pickup"}]'::jsonb, '{"m1":{"confidence":"Directional","note":"owner''s impression from casual conversation, not systematically tracked"}}'::jsonb,
  '{"business_situation":"Claymind Studio is a Penang-based craft workshop business targeting adults seeking creative outlets and stress relief. Their core revenue comes from in-person pottery/craft workshops and take-home starter kits sold at class end. The studio cannot expand session volume due to physical space constraints, so growth must come from increasing repeat attendance within existing capacity. The central problem is a high drop-off rate after first attendance. A structurally important gap exists between the workshop itself and the moment the customer collects their finished, fired piece — a period during which no follow-up currently occurs.","growth_constraints":["Studio space is a hard ceiling — no additional workshop slots can be added","Cannot rely on discounting as a growth lever","Evidence quality is low: based on owner impression, not tracked data","The firing/glazing gap is a structural feature of the medium, not easily shortened"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"The firing/glazing gap is a structurally dead period where customer excitement is highest but zero commercial engagement occurs. A deliberate intervention during this gap would close the loop without requiring more slots or discounts.","supporting_evidence":["Owner observes that most people attend once and do not rebook even when they express loving it","The firing/glazing gap is a structural delay during which no follow-up currently happens","Take-home starter kits are already sold at end of class, confirming an existing habit of converting the post-workshop moment"],"missing_evidence":["How long is the typical firing/glazing gap in practice","What is the actual rebooking rate as a tracked metric","Do customers currently receive any communication between workshop end and pickup","What is the pickup experience currently like","Are there multiple workshop types or skill levels customers could progress through"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"business_situation":"Claymind Studio is a Penang-based craft workshop business targeting adults seeking creative outlets and stress relief. Their core revenue comes from in-person pottery/craft workshops and take-home starter kits sold at class end. The studio cannot expand session volume due to physical space constraints, so growth must come from increasing repeat attendance within existing capacity. The central problem is a high drop-off rate after first attendance. A structurally important gap exists between the workshop itself and the moment the customer collects their finished, fired piece — a period during which no follow-up currently occurs.","growth_constraints":["Studio space is a hard ceiling — no additional workshop slots can be added","Cannot rely on discounting as a growth lever","Evidence quality is low: based on owner impression, not tracked data","The firing/glazing gap is a structural feature of the medium, not easily shortened"],"opportunities":[{"moment_id":"m1","rank":1,"rationale":"The firing/glazing gap is a structurally dead period where customer excitement is highest but zero commercial engagement occurs. A deliberate intervention during this gap would close the loop without requiring more slots or discounts.","supporting_evidence":["Owner observes that most people attend once and do not rebook even when they express loving it","The firing/glazing gap is a structural delay during which no follow-up currently happens","Take-home starter kits are already sold at end of class, confirming an existing habit of converting the post-workshop moment"],"missing_evidence":["How long is the typical firing/glazing gap in practice","What is the actual rebooking rate as a tracked metric","Do customers currently receive any communication between workshop end and pickup","What is the pickup experience currently like","Are there multiple workshop types or skill levels customers could progress through"]}],"recommended_priority_moment_id":"m1"}'::jsonb, '{"growth_hypothesis":"We believe that first-time workshop attendees who receive a personalised message midway through the firing/glazing gap — acknowledging their piece and including a specific, low-friction invite to book a next workshop — will rebook at a meaningfully higher rate than attendees who currently receive no contact during that gap.","thirty_day_test":"Collect the mobile number or email of every first-time workshop attendee at the end of their session. Midway through their firing/glazing wait, send a single personalised message that names the piece they made, tells them it is progressing through firing/glazing, and includes one specific upcoming workshop they could book next, with a direct booking link. No discount is offered.","target_audience":"First-time workshop attendees at Claymind Studio who have completed a session and are waiting for their piece to be fired and glazed","offer_intervention":"A single mid-gap personalised message acknowledging the specific piece and presenting one concrete next workshop to book, with a direct link — no discount, no pressure sequence","conversion_path":"Attendee finishes workshop → staff collect contact detail and note estimated firing/glazing midpoint → at midpoint, staff send personalised message referencing their piece and linking to one specific upcoming workshop → customer books or does not → outcome recorded","evidence_signals":["Number of first-time attendees successfully enrolled into the sequence","Message open or read rate, if platform allows visibility","Number of recipients who book a follow-up workshop within 30 days","Rebooking rate among messaged attendees versus a rough historical baseline","Any direct replies or responses to the message","Whether staff find the manual send process sustainable"],"decision_rule":"Once the 30-day test has run: Scale if 20% or more of messaged attendees book a follow-up session. Retest (10–19%) if the signal is present but content/timing/collection was a likely limiting factor. Shift if fewer than 10% rebook but engagement is positive. Stop if fewer than 10% rebook and engagement is low or negative. Treat as void and Retest with a revised collection method if fewer than half of attendees were successfully enrolled.","decision_rationale":"No version of this intervention has been attempted at Claymind Studio. The diagnosis confirms the problem is real and the gap is structurally present, but confirming the problem exists is not evidence that this specific fix works. Hold is the only honest answer when a hypothesis has not yet been tested.","decision_outcome":"Hold"}'::jsonb, '{"growth_hypothesis":"We believe that first-time workshop attendees who receive a personalised message midway through the firing/glazing gap — acknowledging their piece and including a specific, low-friction invite to book a next workshop — will rebook at a meaningfully higher rate than attendees who currently receive no contact during that gap.","thirty_day_test":"Collect the mobile number or email of every first-time workshop attendee at the end of their session. Midway through their firing/glazing wait, send a single personalised message that names the piece they made, tells them it is progressing through firing/glazing, and includes one specific upcoming workshop they could book next, with a direct booking link. No discount is offered.","target_audience":"First-time workshop attendees at Claymind Studio who have completed a session and are waiting for their piece to be fired and glazed","offer_intervention":"A single mid-gap personalised message acknowledging the specific piece and presenting one concrete next workshop to book, with a direct link — no discount, no pressure sequence","conversion_path":"Attendee finishes workshop → staff collect contact detail and note estimated firing/glazing midpoint → at midpoint, staff send personalised message referencing their piece and linking to one specific upcoming workshop → customer books or does not → outcome recorded","evidence_signals":["Number of first-time attendees successfully enrolled into the sequence","Message open or read rate, if platform allows visibility","Number of recipients who book a follow-up workshop within 30 days","Rebooking rate among messaged attendees versus a rough historical baseline","Any direct replies or responses to the message","Whether staff find the manual send process sustainable"],"decision_rule":"Once the 30-day test has run: Scale if 20% or more of messaged attendees book a follow-up session. Retest (10–19%) if the signal is present but content/timing/collection was a likely limiting factor. Shift if fewer than 10% rebook but engagement is positive. Stop if fewer than 10% rebook and engagement is low or negative. Treat as void and Retest with a revised collection method if fewer than half of attendees were successfully enrolled.","decision_rationale":"No version of this intervention has been attempted at Claymind Studio. The diagnosis confirms the problem is real and the gap is structurally present, but confirming the problem exists is not evidence that this specific fix works. Hold is the only honest answer when a hypothesis has not yet been tested.","decision_outcome":"Hold"}'::jsonb,
